void UPedestrianBehavior::MoveTowardsGoal()
{
    FVector Direction = GoalLocation - Owner->GetActorLocation();
    Direction.Normalize();

    FRotator NewRotation = UKismetMathLibrary::FindLookAtRotation(Owner->GetActorLocation(), GoalLocation);
    Owner->SetActorRotation(NewRotation);

    Owner->AddMovementInput(Direction, Speed * GetWorld()->GetDeltaSeconds());
}

void UPedestrianBehavior::AvoidObstacles()
{
    // Example obstacle avoidance logic
    for (FHitResult Hit : Owner->LineTraceByChannel(Owner->GetActorLocation(), Owner->GetActorLocation() + Owner->GetActorForwardVector() * 100.0f, ECC_WorldStatic))
    {
        if (Hit.GetActor())
        {
            FVector AvoidDirection = Hit.ImpactNormal.RotateAngleAxis(TurnRate, Owner->GetActorUpVector());
            Owner->AddMovementInput(AvoidDirection, Speed * GetWorld()->GetDeltaSeconds());
        }
    }
}

void UPedestrianBehavior::SocialInteractions()
{
    // Example social interaction logic
    for (APedestrian* OtherPedestrian : TActorRange<APedestrian>(GetWorld()))
    {
        if (OtherPedestrian != Owner)
        {
            FVector Distance = OtherPedestrian->GetActorLocation() - Owner->GetActorLocation();
            if (Distance.Size() < AvoidanceRadius)
            {
                FVector AvoidDirection = -Distance.GetSafeNormal();
                Owner->AddMovementInput(AvoidDirection, Speed * GetWorld()->GetDeltaSeconds());
            }
        }
    }
}
