// UPedestrianBehavior.cpp
#include "PedestrianBehavior.h"
#include "Pedestrian/Pedestrian.h"
#include "Kismet/KismetMathLibrary.h"
#include "Engine/World.h"

UPedestrianBehavior::UPedestrianBehavior()
{
    // Constructor
}

void UPedestrianBehavior::Initialize()
{
    Super::Initialize();
    OnInitialize();
}

void UPedestrianBehavior::Update()
{
    Super::Update();
    OnUpdate();
}

void UPedestrianBehavior::OnInitialize()
{
    Owner = Cast<AActor>(GetOuter());
    GoalLocation = FVector(100.0f, 100.0f, 0.0f); // Example goal location
}

void UPedestrianBehavior::OnUpdate()
{
    float startTime = FPlatformTime::Seconds();

    MoveTowardsGoal();
    AvoidObstacles();
    SocialInteractions();
    ApplyRandomPerturbation();

    float endTime = FPlatformTime::Seconds();
    float latency = endTime - startTime;

    UE_LOG(LogTemp, Log, TEXT("Pedestrian Behavior Update Latency: %f ms"), latency * 1000);
}

void UPedestrianBehavior::MoveTowardsGoal()
{
    FVector Direction = GoalLocation - Owner->GetActorLocation();
    Direction.Normalize();

    FRotator NewRotation = UKismetMathLibrary::FindLookAtRotation(Owner->GetActorLocation(), GoalLocation);
    Owner->SetActorRotation(NewRotation);

    Owner->AddMovementInput(Direction, Speed * GetWorld()->GetDeltaSeconds());
}

void UPedestrianBehavior::AvoidObstacles()
{
    // Example obstacle avoidance logic
    for (FHitResult Hit : Owner->LineTraceByChannel(Owner->GetActorLocation(), Owner->GetActorLocation() + Owner->GetActorForwardVector() * 100.0f, ECC_WorldStatic))
    {
        if (Hit.GetActor())
        {
            FVector AvoidDirection = -Hit.ImpactNormal.RotateAngleAxis(TurnRate, Owner->GetActorUpVector());
            Owner->AddMovementInput(AvoidDirection, Speed * GetWorld()->GetDeltaSeconds());
        }
    }
}

void UPedestrianBehavior::SocialInteractions()
{
    // Example social interaction logic
    for (APedestrian* OtherPedestrian : TActorRange<APedestrian>(GetWorld()))
    {
        if (OtherPedestrian != Owner)
        {
            FVector Distance = OtherPedestrian->GetActorLocation() - Owner->GetActorLocation();
            if (Distance.Size() < AvoidanceRadius)
            {
                FVector AvoidDirection = -Distance.GetSafeNormal();
                Owner->AddMovementInput(AvoidDirection, Speed * GetWorld()->GetDeltaSeconds());
            }
        }
    }
}

void UPedestrianBehavior::ApplyRandomPerturbation()
{
    // Apply small random perturbations to the movement direction and speed
    FVector RandomDirection = FVector(FMath::FRandRange(-RandomnessFactor, RandomnessFactor),
                                      FMath::FRandRange(-RandomnessFactor, RandomnessFactor),
                                      0.0f);
    Owner->AddMovementInput(RandomDirection, Speed * GetWorld()->GetDeltaSeconds());

    // Vary the speed slightly
    float RandomSpeed = Speed + FMath::FRandRange(-SpeedVariation, SpeedVariation);
    Owner->AddMovementInput(Owner->GetActorForwardVector(), RandomSpeed * GetWorld()->GetDeltaSeconds());
}
