void UPedestrianBehavior::GroupWithOthers()
{
    // Example grouping logic
    TArray<APedestrian*> NearbyPedestrians;
    for (APedestrian* OtherPedestrian : TActorRange<APedestrian>(GetWorld()))
    {
        if (OtherPedestrian != Owner && !bIsFollowingLeader)
        {
            FVector Distance = OtherPedestrian->GetActorLocation() - Owner->GetActorLocation();
            if (Distance.Size() < 5.0f)
            {
                NearbyPedestrians.Add(OtherPedestrian);
            }
        }
    }

    if (NearbyPedestrians.Num() > 0)
    {
        int32 LeaderIndex = FMath::RandRange(0, NearbyPedestrians.Num() - 1);
        Leader = NearbyPedestrians[LeaderIndex];
        bIsFollowingLeader = true;
    }
}

void UPedestrianBehavior::FollowLeader()
{
    if (bIsFollowingLeader && Leader)
    {
        FVector Direction = Leader->GetActorLocation() - Owner->GetActorLocation();
        Direction.Normalize();

        FRotator NewRotation = UKismetMathLibrary::FindLookAtRotation(Owner->GetActorLocation(), Leader->GetActorLocation());
        Owner->SetActorRotation(NewRotation);

        Owner->AddMovementInput(Direction, Speed * GetWorld()->GetDeltaSeconds());
    }
}

void UPedestrianBehavior::ReactToTrafficLights()
{
    // Example traffic light reaction logic
    for (ATrafficLight* TrafficLight : TActorRange<ATrafficLight>(GetWorld()))
    {
        FVector Distance = TrafficLight->GetActorLocation() - Owner->GetActorLocation();
        if (Distance.Size() < 10.0f)
        {
            if (TrafficLight->IsRed())
            {
                bIsWaitingForTrafficLight = true;
                Owner->StopMovement();
            }
            else if (TrafficLight->IsGreen())
            {
                bIsWaitingForTrafficLight = false;
                if (TimeSinceLastCrossing >= HesitationDelay)
                {
                    bIsCrossing = true;
                    Owner->AddMovementInput(TrafficLight->GetCrossingDirection(), Speed * GetWorld()->GetDeltaSeconds());
                }
                else
                {
                    TimeSinceLastCrossing += GetWorld()->GetDeltaSeconds();
                }
            }
        }
    }
}

void UPedestrianBehavior::ReactToCrosswalkSignals()
{
    // Example crosswalk signal reaction logic
    for (ACrosswalkSignal* CrosswalkSignal : TActorRange<ACrosswalkSignal>(GetWorld()))
    {
        FVector Distance = CrosswalkSignal->GetActorLocation() - Owner->GetActorLocation();
        if (Distance.Size() < 10.0f)
        {
            if (CrosswalkSignal->IsGreen())
            {
                bIsCrossing = true;
                if (TimeSinceLastCrossing >= HesitationDelay)
                {
                    Owner->AddMovementInput(CrosswalkSignal->GetCrossingDirection(), Speed * GetWorld()->GetDeltaSeconds());
                }
                else
                {
