                }
            }
            else
            {
                bIsCrossing = false;
                Owner->StopMovement();
            }
        }
    }
}

void UPedestrianBehavior::SmoothAccelerationDeceleration()
{
    // Gradually adjust speed to avoid sudden stops
    if (Speed > MinSpeed)
    {
        Speed -= 5.0f * GetWorld()->GetDeltaSeconds();
    }
    else if (Speed < MaxSpeed)
    {
        Speed += 5.0f * GetWorld()->GetDeltaSeconds();
    }
}

void UPedestrianBehavior::PredictivePathPlanning()
{
    // Anticipate potential obstacles and adjust path in advance
    for (float Offset = -100.0f; Offset <= 100.0f; Offset += 50.0f)
    {
        FVector TraceStart = Owner->GetActorLocation();
        FVector TraceEnd = TraceStart + Owner->GetActorForwardVector() * 100.0f + FVector(Offset, 0.0f, 0.0f);

        FHitResult Hit;
        if (GetWorld()->LineTraceSingleByChannel(Hit, TraceStart, TraceEnd, ECC_WorldStatic))
        {
            FVector AvoidDirection = -Hit.ImpactNormal.RotateAngleAxis(TurnRate, Owner->GetActorUpVector());
            Owner->AddMovementInput(AvoidDirection, Speed * GetWorld()->GetDeltaSeconds());
        }
    }
}

void UPedestrianBehavior::AdjustSpeedBasedOnDensity()
{
    // Dynamically adjust speed based on crowd density
    CrowdDensity = 0.0f;
    for (APedestrian* OtherPedestrian : TActorRange<APedestrian>(GetWorld()))
    {
        if (OtherPedestrian != Owner)
        {
            FVector Distance = OtherPedestrian->GetActorLocation() - Owner->GetActorLocation();
            if (Distance.Size() < CrowdDensityThreshold)
            {
                CrowdDensity++;
            }
        }
    }

    if (CrowdDensity > 0)
    {
        Speed = FMath::Clamp(Speed - CrowdDensity * 5.0f, MinSpeed, MaxSpeed);
    }
}
