                        sh "cp -r ${cachePath}/* dependencies"
                    }
                }
            }
        }

        stage('Build') {
            parallel {
                stage('Build Pedestrian') {
                    agent { label 'build-agent' }
                    steps {
                        sh 'make build-pedestrian'
                    }
                }
                stage('Build Vehicle') {
                    agent { label 'build-agent' }
                    steps {
                        sh 'make build-vehicle'
                    }
                }
            }
