#### Centralized Clock Singleton

```cpp
// CentralClock.h
#pragma once

#include "CoreMinimal.h"
#include <atomic>

class FCentralClock
{
public:
    static FCentralClock& GetInstance()
    {
        static FCentralClock instance;
        return instance;
    }

    float GetTime() const
    {
        return Time.load(std::memory_order_acquire);
    }

    void Update(float DeltaTime)
    {
        Time.fetch_add(DeltaTime, std::memory_order_release);
    }

private:
    FCentralClock() : Time(0.0f) {}

    std::atomic<float> Time;
};
