import java.util.HashMap;
import java.util.Map;

public class TrafficSimulationSystem {
    private Map<String, TrafficSignal> signals;
    private Map<String, Vehicle> vehicles;
    private int currentTime;

    public TrafficSimulationSystem() {
        signals = new HashMap<>();
        vehicles = new HashMap<>();
        currentTime = 0;
    }

    public void addSignal(String id, SignalState initialState, int duration) {
        signals.put(id, new TrafficSignal(initialState, duration));
    }

    public void addVehicle(String id, VehicleType type, String startingLocation) {
        vehicles.put(id, new Vehicle(type, startingLocation));
    }

    public void updateSignals() {
        for (TrafficSignal signal : signals.values()) {
            if (currentTime % signal.getAdaptiveDuration() == 0) {
                switch (signal.getCurrentState()) {
                    case RED:
                        signal.setState(SignalState.GREEN);
                        break;
                    case GREEN:
                        signal.setState(SignalState.YELLOW);
                        break;
                    case YELLOW:
                        signal.setState(SignalState.RED);
                        break;
                }
            }
        }
        currentTime++;
    }

    public void moveVehicles() {
        for (Vehicle vehicle : vehicles.values()) {
            vehicle.move(currentTime);
        }
    }

