        Request->SetURL(TrafficDataUrl);
        Request->OnProcessResponse().BindLambda([this](FHttpRequestPtr Request, FHttpResponsePtr Response, bool bWasSuccessful)
        {
            if (bWasSuccessful && Response.IsValid())
            {
                FString ResponseContent = Response->GetContentAsString();
                ParseTrafficData(ResponseContent);
            }
            else
            {
                HandleDataGap();
            }
        });
        Request->ProcessRequest();
    }

    void ParseTrafficData(const FString& Data)
    {
        TSharedPtr<FJsonObject> JsonObject;
        TSharedRef<TJsonReader<>> JsonReader = TJsonReaderFactory<>::Create(Data);
        if (FJsonSerializer::Deserialize(JsonReader, JsonObject) && JsonObject.IsValid())
        {
            TrafficVolume = JsonObject->GetIntegerField(TEXT("vehicles"));
            PedestrianCount = JsonObject->GetIntegerField(TEXT("pedestrians"));
        }
    }

    void HandleDataGap()
    {
        // Use default timings if real-time data is unavailable
        TrafficVolume = 0;
        PedestrianCount = 0;
        UE_LOG(LogTemp, Warning, TEXT("Data gap detected. Using default timings."));
    }

    void UpdateSignalPhase()
    {
        // Change phase
        CurrentPhase = (CurrentPhase + 1) % 4;
        // Update signal state
        UpdateSignalState();
    }

    void UpdateSignalState()
    {
        // Update signal state based on current phase and traffic data
        switch (CurrentPhase)
        {
            case 0:
                // Red phase
                SetSignalColor(RED);
                SetSignalDuration(DefaultRedDuration);
                break;
            case 1:
                // Green phase
                SetSignalColor(GREEN);
                SetSignalDuration(CalculateGreenDuration());
                break;
            case 2:
                // Yellow phase
                SetSignalColor(YELLOW);
                SetSignalDuration(5); // Default yellow light duration in seconds
                break;
            case 3:
                // Off phase
                SetSignalColor(OFF);
                break;
        }
    }

    int32 CalculateGreenDuration()
    {
        // Adjust green light duration based on traffic volume and pedestrian count
        if (TrafficVolume > 100 || PedestrianCount > 50)
        {
            return DefaultGreenDuration + 10; // Increase duration if traffic volume or pedestrian count is high
        }
        else if (TrafficVolume < 50 || PedestrianCount < 25)
        {
            return DefaultGreenDuration - 5; // Decrease duration if traffic volume or pedestrian count is low
        }
        return DefaultGreenDuration;
    }

    void SetSignalColor(EColor Color)
    {
        // Simulate setting the signal color
        UE_LOG(LogTemp, Log, TEXT("Setting signal color to %d"), Color);
    }

    void SetSignalDuration(int32 Duration)
    {
        // Simulate setting the signal duration
        UE_LOG(LogTemp, Log, TEXT("Setting signal duration to %d seconds"), Duration);
    }

    void HandlePedestrianCrossingRequest()
    {
        // Check if the current phase allows pedestrians to cross
        if (CurrentPhase != 1) // Assuming 1 is the green phase for pedestrians
        {
            // Change to the pedestrian crossing phase
            CurrentPhase = 1;
            UpdateSignalState();
        }
    }

private:
    FTimerHandle TimerHandle_PhaseChange;
    float PhaseChangeInterval;
    int32 CurrentPhase;
    FString TrafficDataUrl;
    int32 TrafficVolume;
    int32 PedestrianCount;
    int32 DefaultGreenDuration;
    int32 DefaultRedDuration;
};

// Example usage in a level blueprint or another actor
void SomeOtherActor::SomeFunction()
{
    ATrafficSignal* TrafficSignal = NewObject<ATrafficSignal>();
    TrafficSignal->BeginPlay();

    // Simulate a pedestrian crossing request
    TrafficSignal->HandlePedestrianCrossingRequest();
}
```

