// TrafficSignal.cpp
#include "TrafficSignal.h"

TrafficSignal::TrafficSignal(float greenDuration, float yellowDuration, float redDuration)
    : currentState(TrafficLightState::RED),
      elapsedTime(0.0f),
      greenDuration(greenDuration),
      yellowDuration(yellowDuration),
      redDuration(redDuration) {}

void TrafficSignal::update(float elapsed) {
    elapsedTime += elapsed;

    if (currentState == TrafficLightState::RED && elapsedTime >= redDuration) {
        currentState = TrafficLightState::GREEN;
        elapsedTime = 0.0f;
    } else if (currentState == TrafficLightState::GREEN && elapsedTime >= greenDuration) {
        currentState = TrafficLightState::YELLOW;
        elapsedTime = 0.0f;
    } else if (currentState == TrafficLightState::YELLOW && elapsedTime >= yellowDuration) {
        currentState = TrafficLightState::RED;
        elapsedTime = 0.0f;
    }
}

TrafficLightState TrafficSignal::getCurrentState() const {
    return currentState;
}
