class TrafficSimulation {
public:
    TrafficSimulation(int numIntersections, int numVehicles, float fps)
        : numIntersections(numIntersections), numVehicles(numVehicles), fps(fps) {
        for (int i = 0; i < numIntersections; ++i) {
            intersections.push_back(TrafficIntersection());
        }
        for (int i = 0; i < numVehicles; ++i) {
            vehicles.push_back(TrafficVehicle());
        }
    }

    void runSimulation(int duration) {
        float elapsedTime = 0.0f;
        for (int frame = 0; frame < duration; ++frame) {
            elapsedTime += 1.0f / fps;

            for (auto& intersection : intersections) {
                intersection.update(elapsedTime);
            }

            for (auto& vehicle : vehicles) {
                vehicle.update(elapsedTime);
            }

            renderFrame();
        }
    }

    void renderFrame() {
        // Batch rendering calls
        for (auto& intersection : intersections) {
            intersection.render();
        }
        for (auto& vehicle : vehicles) {
            vehicle.render();
        }
    }

private:
    int numIntersections;
    int numVehicles;
    float fps;
    std::vector<TrafficIntersection> intersections;
    std::vector<TrafficVehicle> vehicles;
};
