#include "PxPhysicsAPI.h"
#include "PxDefaultErrorCallback.h"
#include "PxDefaultAllocator.h"
#include "PxProfileZoneManager.h"
#include "PxTolerancesScale.h"

void InitializePhysX()
{
    // Create the foundation
    physx::PxFoundation* foundation = physx::PxCreateFoundation(
        PX_PHYSICS_VERSION,
        physx::PxDefaultAllocator(),
        physx::PxDefaultErrorCallback());

    // Create the CPU dispatcher
    physx::PxDefaultCpuDispatcher* dispatcher = physx::PxDefaultCpuDispatcher::create(4);

    // Create the profile zone manager
    physx::PxProfileZoneManager* profileZoneManager = physx::PxProfileZoneManager::createProfileZoneManager(foundation);

    // Create the physics SDK
    physx::PxPhysics* physics = physx::PxCreatePhysics(
        PX_PHYSICS_VERSION,
        *foundation,
        physx::PxTolerancesScale(),
        true,
        profileZoneManager);

    // Initialize extensions
    physx::PxInitExtensions(*physics);

    // Store references to these objects for later use
    gFoundation = foundation;
    gDispatcher = dispatcher;
    gProfileZoneManager = profileZoneManager;
    gPhysics = physics;
}
