Use a grid or spatial partitioning technique to reduce the number of pairwise checks:

```cpp
struct GridCell {
    std::vector<physx::PxRigidActor*> actors;
};

class Grid {
public:
    Grid(int width, int height, int cellSize) : width_(width), height_(height), cellSize_(cellSize)
    {
        int numCellsX = width_ / cellSize_;
        int numCellsY = height_ / cellSize_;
        grid_.resize(numCellsX * numCellsY);
    }

    void addActor(physx::PxRigidActor* actor)
    {
        physx::PxTransform transform = actor->getGlobalPose();
        physx::PxVec3 position = transform.p;
        int cellX = static_cast<int>(position.x / cellSize_);
        int cellY = static_cast<int>(position.y / cellSize_);

        if (cellX >= 0 && cellX < grid_.size() && cellY >= 0 && cellY < grid_.size())
        {
            int index = cellX + cellY * grid_.size();
            grid_[index].actors.push_back(actor);
        }
    }

    void detectCollisions()
    {
        for (auto& cell : grid_)
        {
            for (size_t i = 0; i < cell.actors.size(); ++i)
            {
                for (size_t j = i + 1; j < cell.actors.size(); ++j)
                {
                    if (cell.actors[i]->getGlobalPose().p.distanceTo(cell.actors[j]->getGlobalPose().p) < 2.0f)
                    {
                        // Handle collision
                        std::cout << "Collision detected between actors" << std::endl;
                    }
                }
            }
        }
    }

private:
    int width_;
    int height_;
    int cellSize_;
    std::vector<GridCell> grid_;
};
```

