class Agent {
public:
    Agent(float x, float y, float radius) : position_{x, y}, radius_(radius) {}

    float getX() const { return position_[0]; }
    float getY() const { return position_[1]; }
    float getRadius() const { return radius_; }

    bool isColliding(const Agent& other) const {
        float dx = position_[0] - other.position_[0];
        float dy = position_[1] - other.position_[1];
        float distanceSquared = dx * dx + dy * dy;
        float radiusSum = radius_ + other.radius_;
        return distanceSquared < radiusSum * radiusSum;
    }

private:
    std::array<float, 2> position_;
    float radius_;
};

class CollisionDetector {
public:
    CollisionDetector(int numAgents) : numAgents_(numAgents), agents_(numAgents) {}

    void addAgent(const Agent& agent) {
        agents_.push_back(agent);
    }

    void detectCollisions() {
        for (size_t i = 0; i < agents_.size(); ++i) {
            for (size_t j = i + 1; j < agents_.size(); ++j) {
                if (agents_[i].isColliding(agents_[j])) {
                    // Handle collision
                    std::cout << "Collision detected between agents " << i << " and " << j << std::endl;
                }
            }
        }
    }

private:
    int numAgents_;
    std::vector<Agent> agents_;
};

