#include <PxPhysicsAPI.h>
#include <PxDefaultErrorCallback.h>
#include <PxDefaultAllocator.h>
#include <PxProfileZoneManager.h>
#include <PxTolerancesScale.h>
#include <vector>
#include <cmath>

using namespace physx;

class Agent {
public:
    Agent(PxVec3 position, float radius) : position(position), radius(radius) {}
    PxVec3 getPosition() const { return position; }
    float getRadius() const { return radius; }
private:
    PxVec3 position;
    float radius;
};

class QuadTreeNode {
public:
    QuadTreeNode(float x, float y, float width, float height, int capacity)
        : x(x), y(y), width(width), height(height), capacity(capacity) {}

    void subdivide() {
        float halfWidth = width / 2;
        float halfHeight = height / 2;
        children.push_back(std::make_unique<QuadTreeNode>(x, y, halfWidth, halfHeight, capacity));
        children.push_back(std::make_unique<QuadTreeNode>(x + halfWidth, y, halfWidth, halfHeight, capacity));
        children.push_back(std::make_unique<QuadTreeNode>(x, y + halfHeight, halfWidth, halfHeight, capacity));
        children.push_back(std::make_unique<QuadTreeNode>(x + halfWidth, y + halfHeight, halfWidth, halfHeight, capacity));
    }

    bool insert(Agent& agent) {
        if (!contains(agent)) {
            return false;
        }

        if (children.empty()) {
            agents.push_back(&agent);
            if (agents.size() > capacity) {
                if (children.empty()) {
                    subdivide();
                }
                for (auto& a : agents) {
                    for (auto& child : children) {
                        if (child->insert(*a)) {
                            agents.erase(std::remove(agents.begin(), agents.end(), a), agents.end());
                            break;
                        }
                    }
                }
            }
            return true;
        }

        for (auto& child : children) {
            if (child->insert(agent)) {
                return true;
            }
        }
        return false;
    }

    void query(Agent& agent, std::vector<Agent*>& results) {
        if (!contains(agent)) {
            return;
        }

        for (auto& a : agents) {
            if (a != &agent) {
                float distanceSquared = (agent.getPosition() - a->getPosition()).magnitudeSquared();
                if (distanceSquared < (agent.getRadius() + a->getRadius()) * (agent.getRadius() + a->getRadius())) {
                    results.push_back(a);
                }
            }
        }

        for (auto& child : children) {
            child->query(agent, results);
        }
    }

private:
    bool contains(Agent& agent) {
        PxVec3 pos = agent.getPosition();
        return pos.x >= x && pos.x < x + width && pos.y >= y && pos.y < y + height;
    }

    float x, y, width, height;
    int capacity;
    std::vector<Agent*> agents;
    std::vector<std::unique_ptr<QuadTreeNode>> children;
};

class QuadTree {
public:
    QuadTree(float x, float y, float width, float height, int capacity)
        : root(std::make_unique<QuadTreeNode>(x, y, width, height, capacity)) {}

    void insert(Agent& agent) {
        root->insert(agent);
    }

    void query(Agent& agent, std::vector<Agent*>& results) {
        root->query(agent, results);
    }

private:
    std::unique_ptr<QuadTreeNode> root;
};

class PhysXCollisionDetection {
public:
    PhysXCollisionDetection() {
        PxProfileZoneManager* profileZoneManager = PxProfileZoneManager::createProfileZoneManager(PxGetFoundation());
        PxPhysics* physics = PxCreatePhysics(PX_PHYSICS_VERSION, *PxGetFoundation(), PxTolerancesScale(), true, profileZoneManager);
        PxInitExtensions(*physics);

        PxSceneDesc sceneDesc(physics->getTolerancesScale());
        sceneDesc.cpuDispatcher = PxDefaultCpuDispatcherCreate(4);
        sceneDesc.gravity = PxVec3(0.0f, -9.81f, 0.0f);
        scene = physics->createScene(sceneDesc);
    }

    ~PhysXCollisionDetection() {
        scene->release();
        PxCloseExtensions();
        gPhysics->release();
        gProfileZoneManager->release();
        gFoundation->release();
    }

    void addAgent(Agent& agent) {
        PxRigidDynamic* actor = gPhysics->createRigidDynamic(PxTransform(agent.getPosition()));
        PxBoxGeometry boxGeometry(1.0f, 1.0f, 1.0f);
        PxShape* shape = gPhysics->createShape(boxGeometry, *gPhysics->createMaterial(0.5f, 0.5f, 0.6f));
        actor->attachShape(*shape);
        scene->addActor(*actor);
        actors.push_back(actor);
    }

    void simulateAndFetchResults() {
        scene->simulate(1.0f / 60.0f);
        scene->fetchResults(true);
    }

    void detectCollisions() {
        for (auto& actor : actors) {
            PxActorIterator<PxRigidActor> iter = scene->getActors(PxActorTypeFlag::eRIGID_DYNAMIC);
            while (iter.hasNext()) {
                PxRigidActor* otherActor = iter.next();
                if (actor != otherActor) {
                    PxPairFlags flags;
                    PxContactPairHeader* header;
                    PxContactPair* pairs;
                    PxU32 nbPairs = scene->getNbPairs();
                    scene->getPairs(&flags, &header, &pairs, nbPairs);
                    for (PxU32 i = 0; i < nbPairs; i++) {
                        if ((pairs[i].actor[0] == actor || pairs[i].actor[1] == actor) &&
                            (pairs[i].actor[0] == otherActor || pairs[i].actor[1] == otherActor)) {
                            std::cout << "Collision detected between actors" << std::endl;
                        }
                    }
                }
            }
        }
    }

private:
    PxScene* scene;
    std::vector<PxRigidDynamic*> actors;
};

