Let's implement a quad tree to manage the agents and perform collision detection more efficiently.

### Step 1: Define the Quad Tree Node

A quad tree node will represent a region of space and contain references to its four children (sub-regions).

```python
import numpy as np

class QuadTreeNode:
    def __init__(self, x, y, width, height):
        self.x = x
        self.y = y
        self.width = width
        self.height = height
        self.agents = []
        self.children = None

    def subdivide(self):
        half_width = self.width / 2
        half_height = self.height / 2
        self.children = [
            QuadTreeNode(self.x, self.y, half_width, half_height),
            QuadTreeNode(self.x + half_width, self.y, half_width, half_height),
            QuadTreeNode(self.x, self.y + half_height, half_width, half_height),
            QuadTreeNode(self.x + half_width, self.y + half_height, half_width, half_height)
        ]

    def insert(self, agent):
        if self.children:
            for child in self.children:
                if child.contains(agent):
                    child.insert(agent)
                    return
        else:
            self.agents.append(agent)
            if len(self.agents) > 1:
                self.subdivide()
                for agent in self.agents:
                    for child in self.children:
                        if child.contains(agent):
                            child.insert(agent)
                            break
                self.agents.clear()

    def contains(self, agent):
        pos = agent.position
        return (
            pos[0] >= self.x and
            pos[0] < self.x + self.width and
            pos[1] >= self.y and
            pos[1] < self.y + self.height
        )

    def query(self, agent):
        results = []
        if self.children:
            for child in self.children:
                if child.contains(agent):
                    results.extend(child.query(agent))
        else:
            for other_agent in self.agents:
                if other_agent != agent:
                    results.append(other_agent)
        return results
```

