```python
import numpy as np

class Agent:
    def __init__(self, position, radius):
        self.position = np.array(position)
        self.radius = radius

def calculate_squared_distance(pos1, pos2):
    return np.sum((pos1 - pos2) ** 2)

def calculate_overlap(agent1, agent2):
    squared_distance = calculate_squared_distance(agent1.position, agent2.position)
    squared_sum_of_radii = (agent1.radius + agent2.radius) ** 2
    return squared_distance < squared_sum_of_radii

class SpatialPartition:
    def __init__(self, agents, grid_size):
        self.agents = agents
        self.grid_size = grid_size
        self.grid = {}

    def partition_agents(self):
        for agent in self.agents:
            grid_cell = self.get_grid_cell(agent.position)
            if grid_cell not in self.grid:
                self.grid[grid_cell] = []
            self.grid[grid_cell].append(agent)

    def get_grid_cell(self, position):
        return (position[0] // self.grid_size, position[1] // self.grid_size)

    def detect_overlaps(self):
        overlaps = []
        for grid_cell in self.grid:
            agents_in_cell = self.grid[grid_cell]
            for i in range(len(agents_in_cell)):
                for j in range(i + 1, len(agents_in_cell)):
                    if calculate_overlap(agents_in_cell[i], agents_in_cell[j]):
                        overlaps.append((agents_in_cell[i], agents_in_cell[j]))

            # Check neighboring cells
            for dx in [-1, 0, 1]:
                for dy in [-1, 0, 1]:
                    if dx == 0 and dy == 0:
                        continue
                    neighbor_cell = (grid_cell[0] + dx, grid_cell[1] + dy)
                    if neighbor_cell in self.grid:
                        for agent1 in agents_in_cell:
                            for agent2 in self.grid[neighbor_cell]:
                                if calculate_overlap(agent1, agent2):
                                    overlaps.append((agent1, agent2))
        return overlaps

def main_simulation_loop(num_agents=100, num_steps=100, grid_size=10):
    # Create a list of agents
    agents = [Agent((i, i), 1) for i in range(num_agents)]

    # Initialize the spatial partition
    spatial_partition = SpatialPartition(agents, grid_size)
    spatial_partition.partition_agents()

    for step in range(num_steps):
        print(f"Simulation Step: {step}")

        # Detect overlaps
        overlaps = spatial_partition.detect_overlaps()
        for agent1, agent2 in overlaps:
            print(f"Overlap detected between {agent1} and {agent2}")

        # Update positions
        for agent in agents:
            agent.position += np.array([1, 1])  # Example update

# Run the main simulation loop
main_simulation_loop()
