#include "BoundingBox.h"

BoundingBox::BoundingBox(const Vector3& position, float width, float height, float depth) :
    position_(position),
    width_(width),
    height_(height),
    depth_(depth) {}

bool BoundingBox::Intersects(const BoundingBox& other) const {
    if (position_.x + width_ > other.position_.x && position_.x < other.position_.x + other.width_) {
        if (position_.y + height_ > other.position_.y && position_.y < other.position_.y + other.height_) {
            if (position_.z + depth_ > other.position_.z && position_.z < other.position_.z + other.depth_) {
                return true;
            }
        }
    }

    return false;
}

BoundingBox BoundingBox::Tighten(float factor) const {
    float tightenedWidth = width_ * (1.0f - factor);
    float tightenedHeight = height_ * (1.0f - factor);
    float tightenedDepth = depth_ * (1.0f - factor);

    return BoundingBox(position_, tightenedWidth, tightenedHeight, tightenedDepth);
}
