    std::vector<Object*> QueryCollisions(const BoundingBox& boundingBox) const;
    void InsertObject(QuadtreeNode* node, Object* object);
    void RemoveObject(QuadtreeNode* node, Object* object);
    void Subdivide(QuadtreeNode* node);
    QuadtreeNode* GetChildNode(QuadtreeNode* node, Object* object) const;
