    struct QuadtreeNode {
        float x, y;          // Center of the region
        float width, height; // Dimensions of the region
        std::vector<Object*> objects; // Objects in this region
        QuadtreeNode* nw;    // North-West child
        QuadtreeNode* ne;    // North-East child
        QuadtreeNode* sw;    // South-West child
        QuadtreeNode* se;    // South-East child

        QuadtreeNode(float x, float y, float width, float height)
            : x(x), y(y), width(width), height(height), nw(nullptr), ne(nullptr), sw(nullptr), se(nullptr) {}
    };
};

// CollisionDetection.cpp
#include "CollisionDetection.h"

CollisionDetection::CollisionDetection(float worldWidth, float worldHeight)
    : worldWidth(worldWidth), worldHeight(worldHeight) {
    // Initialize the root node of the quadtree
    rootNode = new QuadtreeNode(worldWidth / 2.0f, worldHeight / 2.0f, worldWidth, worldHeight);
}

CollisionDetection::~CollisionDetection() {
    // Clean up the quadtree
    ClearTree(rootNode);
    delete rootNode;
}

void CollisionDetection::ClearTree(QuadtreeNode* node) {
    if (node->nw != nullptr) {
        ClearTree(node->nw);
        ClearTree(node->ne);
        ClearTree(node->sw);
        ClearTree(node->se);
    }
    delete node;
}

void CollisionDetection::AddObject(Object* object) {
    InsertObject(rootNode, object);
}

void CollisionDetection::RemoveObject(Object* object) {
    RemoveObject(rootNode, object);
}

void CollisionDetection::InsertObject(QuadtreeNode* node, Object* object) {
    if (node->nw == nullptr) {
        node->objects.push_back(object);
        if (node->objects.size() > MAX_OBJECTS_PER_NODE) {
            Subdivide(node);
            for (auto obj : node->objects) {
                InsertObject(GetChildNode(node, obj), obj);
            }
            node->objects.clear();
        }
    } else {
        InsertObject(GetChildNode(node, object), object);
    }
}

void CollisionDetection::RemoveObject(QuadtreeNode* node, Object* object) {
    if (node->nw == nullptr) {
        node->objects.erase(std::remove(node->objects.begin(), node->objects.end(), object), node->objects.end());
    } else {
        RemoveObject(GetChildNode(node, object), object);
    }
}

void CollisionDetection::Subdivide(QuadtreeNode* node) {
    float halfWidth = node->width / 2.0f;
    float halfHeight = node->height / 2.0f;

    node->nw = new QuadtreeNode(node->x - halfWidth, node->y + halfHeight, halfWidth, halfHeight);
    node->ne = new QuadtreeNode(node->x + halfWidth, node->y + halfHeight, halfWidth, halfHeight);
    node->sw = new QuadtreeNode(node->x - halfWidth, node->y - halfHeight, halfWidth, halfHeight);
    node->se = new QuadtreeNode(node->x + halfWidth, node->y - halfHeight, halfWidth, halfHeight);
}

QuadtreeNode* CollisionDetection::GetChildNode(QuadtreeNode* node, Object* object) const {
    float x = object->GetPosition().x;
    float y = object->GetPosition().y;
    float halfWidth = node->width / 2.0f;
    float halfHeight = node->height / 2.0f;

    if (x < node->x && y >= node->y) {
        return node->nw;
    } else if (x >= node->x && y >= node->y) {
        return node->ne;
    } else if (x < node->x && y < node->y) {
        return node->sw;
    } else {
        return node->se;
    }
}

std::vector<Object*> CollisionDetection::QueryCollisions(const BoundingBox& boundingBox) const {
    std::vector<Object*> result;

    if (rootNode->nw == nullptr) {
        for (auto obj : rootNode->objects) {
            if (obj->GetBoundingBox().Intersects(boundingBox)) {
                result.push_back(obj);
            }
        }
    } else {
        if (boundingBox.Intersects(rootNode->nw->x, rootNode->nw->y, rootNode->nw->width, rootNode->nw->height)) {
            std::vector<Object*> temp = QueryCollisions(rootNode->nw, boundingBox);
            result.insert(result.end(), temp.begin(), temp.end());
        }
        if (boundingBox.Intersects(rootNode->ne->x, rootNode->ne->y, rootNode->ne->width, rootNode->ne->height)) {
            std::vector<Object*> temp = QueryCollisions(rootNode->ne, boundingBox);
            result.insert(result.end(), temp.begin(), temp.end());
        }
        if (boundingBox.Intersects(rootNode->sw->x, rootNode->sw->y, rootNode->sw->width, rootNode->sw->height)) {
            std::vector<Object*> temp = QueryCollisions(rootNode->sw, boundingBox);
            result.insert(result.end(), temp.begin(), temp.end());
        }
        if (boundingBox.Intersects(rootNode->se->x, rootNode->se->y, rootNode->se->width, rootNode->se->height)) {
            std::vector<Object*> temp = QueryCollisions(rootNode->se, boundingBox);
            result.insert(result.end(), temp.begin(), temp.end());
        }
    }

    return result;
}

bool CollisionDetection::CheckCollision(const Vector3& position, const Vector3& velocity) const {
    BoundingBox boundingBox = CalculateBoundingBox(position, velocity);
    std::vector<Object*> potentialColliders = QueryCollisions(boundingBox);

    for (auto collider : potentialColliders) {
        if (collider->GetBoundingBox().Intersects(boundingBox)) {
            return true;
        }
    }

    return false;
}

BoundingBox CollisionDetection::CalculateBoundingBox(const Vector3& position, const Vector3& velocity) const {
    float width = 1.0f;
    float height = 1.0f;
    float depth = 1.0f;

    return BoundingBox(position, width, height, depth);
}
