ATrafficSignal::ATrafficSignal()
{
    PrimaryActorTick.bCanEverTick = true;
    CurrentState = SignalState::Red;
    CycleDuration = 60.0f;  // Example cycle duration
    CurrentCycleTime = 0.0f;
}

void ATrafficSignal::BeginPlay()
{
    Super::BeginPlay();
}

void ATrafficSignal::Tick(float DeltaTime)
{
    Super::Tick(DeltaTime);
    CurrentCycleTime += DeltaTime;
    UpdateSignalState();
}

void ATrafficSignal::UpdateSignalState()
{
    if (CurrentCycleTime >= CycleDuration)
    {
        CurrentCycleTime = 0.0f;
        switch (CurrentState)
        {
            case SignalState::Red:
                CurrentState = SignalState::Green;
                break;
            case SignalState::Green:
                CurrentState = SignalState::Yellow;
                break;
            case SignalState::Yellow:
                CurrentState = SignalState::Red;
                break;
            default:
                break;
        }
    }
}
