To implement spatial partitioning using quad trees to optimize collision checks in your traffic agent setup, you can follow these steps:

### Steps to Implement Quad Trees

1. **Define the Quad Tree Structure**:
   - Create a quad tree node structure that can hold a list of objects (vehicles or pedestrians) and four child nodes (one for each quadrant).

2. **Insert Objects into the Quad Tree**:
   - Insert each object (vehicle or pedestrian) into the appropriate leaf node of the quad tree based on its position.

3. **Query the Quad Tree for Collisions**:
   - Query the quad tree to find potential collisions by checking only the relevant nodes that contain objects within the bounding box of interest.

4. **Maintain Consistency**:
   - Ensure that the quad tree is updated whenever objects are moved, added, or removed to maintain consistency.

### Example Implementation

Here's an example implementation that integrates quad trees into your traffic agent setup:

```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <algorithm>

struct Vector2 {
    float x, y;
    Vector2(float x, float y) : x(x), y(y) {}
};

struct BoundingBox {
    Vector2 min, max;
    BoundingBox(Vector2 min, Vector2 max) : min(min), max(max) {}
};

class QuadTreeNode {
public:
    BoundingBox bounds;
    std::vector<int> objects;
    std::array<std::unique_ptr<QuadTreeNode>, 4> children;

    QuadTreeNode(BoundingBox bounds) : bounds(bounds) {}

    void insert(int id, const BoundingBox& objBounds) {
        if (!boundsIntersects(objBounds)) return;

        if (children[0]) {
            for (auto& child : children) {
                if (child && child->boundsContains(objBounds.min)) {
                    child->insert(id, objBounds);
                    return;
                }
            }
        }

        objects.push_back(id);

        if (objects.size() > 4 && !children[0]) {
            subdivide();
            for (auto objId : objects) {
                for (auto& child : children) {
                    if (child && child->boundsContains(objBounds.min)) {
                        child->insert(objId, objBounds);
                        break;
                    }
                }
            }
            objects.clear();
        }
    }

    void query(const BoundingBox& queryBounds, std::vector<int>& results) const {
        if (!boundsIntersects(queryBounds)) return;

        for (const auto& objId : objects) {
            results.push_back(objId);
        }

        for (const auto& child : children) {
            if (child) {
                child->query(queryBounds, results);
            }
        }
    }

private:
    bool boundsIntersects(const BoundingBox& objBounds) const {
        return !(objBounds.max.x < bounds.min.x || objBounds.min.x > bounds.max.x ||
                 objBounds.max.y < bounds.min.y || objBounds.min.y > bounds.max.y);
    }

    bool boundsContains(const Vector2& point) const {
        return point.x >= bounds.min.x && point.x <= bounds.max.x &&
               point.y >= bounds.min.y && point.y <= bounds.max.y;
    }

    void subdivide() {
        float halfWidth = (bounds.max.x - bounds.min.x) / 2.0f;
        float halfHeight = (bounds.max.y - bounds.min.y) / 2.0f;

        children[0] = std::make_unique<QuadTreeNode>(BoundingBox(
            Vector2(bounds.min.x, bounds.min.y),
            Vector2(bounds.min.x + halfWidth, bounds.min.y + halfHeight)));

        children[1] = std::make_unique<QuadTreeNode>(BoundingBox(
            Vector2(bounds.min.x + halfWidth, bounds.min.y),
            Vector2(bounds.max.x, bounds.min.y + halfHeight)));

        children[2] = std::make_unique<QuadTreeNode>(BoundingBox(
            Vector2(bounds.min.x, bounds.min.y + halfHeight),
            Vector2(bounds.min.x + halfWidth, bounds.max.y)));

        children[3] = std::make_unique<QuadTreeNode>(BoundingBox(
            Vector2(bounds.min.x + halfWidth, bounds.min.y + halfHeight),
            Vector2(bounds.max.x, bounds.max.y)));
    }
};

class Vehicle {
public:
    int id;
    Vector2 position;
    float width, height;

    Vehicle(int id, Vector2 position, float width, float height)
        : id(id), position(position), width(width), height(height) {}

    BoundingBox getBoundingBox() const {
        return BoundingBox(Vector2(position.x - width / 2, position.y - height / 2),
                           Vector2(position.x + width / 2, position.y + height / 2));
    }
};

class TrafficAgent {
private:
    std::unordered_map<int, Vehicle> vehicles;
    std::unique_ptr<QuadTreeNode> quadTree;
    std::mutex mtx;

public:
    TrafficAgent(BoundingBox worldBounds)
        : quadTree(std::make_unique<QuadTreeNode>(worldBounds)) {}

    void addVehicle(const Vehicle& vehicle) {
        std::lock_guard<std::mutex> lock(mtx);
        vehicles[vehicle.id] = vehicle;
        quadTree->insert(vehicle.id, vehicle.getBoundingBox());
    }

    void removeVehicle(int id) {
        std::lock_guard<std::mutex> lock(mtx);
        if (vehicles.find(id) != vehicles.end()) {
            quadTree->remove(id, vehicles[id].getBoundingBox());
            vehicles.erase(id);
        }
    }

    void moveVehicle(int id, Vector2 delta) {
        std::lock_guard<std::mutex> lock(mtx);
        if (vehicles.find(id) != vehicles.end()) {
            Vehicle& vehicle = vehicles[id];
            BoundingBox oldBounds = vehicle.getBoundingBox();
            vehicle.position.x += delta.x;
            vehicle.position.y += delta.y;
            BoundingBox newBounds = vehicle.getBoundingBox();
            quadTree->move(id, oldBounds, newBounds);
        }
    }

    void checkCollisions() {
        std::lock_guard<std::mutex> lock(mtx);
        for (const auto& pair : vehicles) {
            const Vehicle& vehicle = pair.second;
            BoundingBox vehicleBounds = vehicle.getBoundingBox();
            std::vector<int> potentialColliders;
            quadTree->query(vehicleBounds, potentialColliders);

            for (int colliderId : potentialColliders) {
                if (colliderId != vehicle.id && vehicles[colliderId].getBoundingBox().overlaps(vehicleBounds)) {
                    std::cout << "Collision detected between vehicles " << vehicle.id << " and " << colliderId << std::endl;
                }
            }
        }
    }
};

int main() {
    BoundingBox worldBounds(Vector2(0, 0), Vector2(100, 100));
    TrafficAgent agent(worldBounds);

    // Add vehicles
    agent.addVehicle(Vehicle(1, Vector2(10, 10), 10, 10));
    agent.addVehicle(Vehicle(2, Vector2(20, 20), 10, 10));

    // Move vehicles
    agent.moveVehicle(1, Vector2(5, 5));

    // Check for collisions
    agent.checkCollisions();

    return 0;
}
```

### Explanation

1. **Quad Tree Structure**:
   - `QuadTreeNode` represents a node in the quad tree, containing a bounding box and a list of objects.
   - It also contains four child nodes representing the four quadrants.

2. **Insert Objects**:
   - The `insert` method adds an object to the quad tree, recursively subdividing the node if necessary.

3. **Query the Quad Tree**:
   - The `query` method retrieves potential colliders within a given bounding box, checking only relevant nodes.

4. **Maintain Consistency**:
   - Ensure that the quad tree is updated whenever objects are moved, added, or removed.
   - Use a mutex (`mtx`) to synchronize access to shared data.

### Additional Considerations

- **Concurrency**:
  - If you are running in a multithreaded environment, ensure that each thread has its own instance of `TrafficAgent` or use thread-safe mechanisms to share instances.
  - Use thread pools or async/await patterns to handle the increased load efficiently.

- **Performance Optimization**:
  - Use spatial partitioning techniques like quad trees to optimize collision checks.
  - Batch process collision checks to reduce the overhead of individual updates.

