class GridBasedCollisionOptimizer {
private:
    ros::NodeHandle nh_;
    ros::Subscriber pose_sub_;
    ros::Publisher collision_pub_;
    std::unordered_map<int, geometry_msgs::PoseStamped> agents_;
    std::vector<std::vector<std::vector<int>>> grid_;
    int grid_size_;
    double cell_width_, cell_height_;
    std::mutex mtx_;

    void initializeGrid(double width, double height, int grid_size) {
        grid_size_ = grid_size;
        cell_width_ = width / grid_size_;
        cell_height_ = height / grid_size_;
        grid_.resize(grid_size_);
        for (auto& row : grid_) {
            row.resize(grid_size_);
        }
    }

    int getCellIndex(double value, double cell_size) {
        return std::floor(value / cell_size);
    }

    void updateGrid(int id, const geometry_msgs::PoseStamped& pose) {
        int x_index = getCellIndex(pose.pose.position.x, cell_width_);
        int y_index = getCellIndex(pose.pose.position.y, cell_height_);

        // Remove from old cell
        auto it = std::find(grid_[x_index][y_index].begin(), grid_[x_index][y_index].end(), id);
        if (it != grid_[x_index][y_index].end()) {
            grid_[x_index][y_index].erase(it);
        }

        // Add to new cell
        grid_[x_index][y_index].push_back(id);
    }

    void poseCallback(const geometry_msgs::PoseStamped::ConstPtr& msg) {
        std::lock_guard<std::mutex> lock(mtx_);
