        std::lock_guard<std::mutex> lock(mtx_);
        for (int i = 0; i < grid_size_; ++i) {
            for (int j = 0; j < grid_size_; ++j) {
                if (!grid_[i][j].empty()) {
                    for (int k = -1; k <= 1; ++k) {
                        for (int l = -1; l <= 1; ++l) {
                            int ni = i + k;
                            int nj = j + l;
                            if (ni >= 0 && ni < grid_size_ && nj >= 0 && nj < grid_size_) {
                                for (int id1 : grid_[i][j]) {
                                    for (int id2 : grid_[ni][nj]) {
                                        if (id1 == id2) continue;
                                        const auto& pose1 = agents_[id1];
                                        const auto& pose2 = agents_[id2];
                                        if (pose1.pose.position.x == pose2.pose.position.x &&
                                            pose1.pose.position.y == pose2.pose.position.y) {
