                                            msg.data = "Collision detected between agents " + std::to_string(id1) + " and "_s + std::to_string(id2);
                                            collision_pub_.publish(msg);
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

