#### Step 2: Create Actors and Shapes

Define the actors and their shapes:

```cpp
void createActor(PxPhysics* physics, PxScene* scene, PxVec3 position, PxVec3 dimensions, PxMaterial* material, PxRigidActor** actor) {
    PxShape* shape = PxCreateDynamicBoxShape(dimensions, material);
    PxRigidDynamic* rigidActor = PxCreateRigidDynamic(*physics, PxTransform(position), *shape);
    scene->addActor(*rigidActor);
    *actor = rigidActor;
}
```

#### Step 3: Perform Overlap Queries

Use PhysX overlap queries to check for collisions:

```cpp
bool checkCollision(PxScene* scene, PxRigidActor* actor1, PxRigidActor* actor2) {
    PxOverlapBuffer buffer;
    PxShape* shape1 = actor1->getShapes()[0];
    PxShape* shape2 = actor2->getShapes()[0];

    PxVec3 pos1 = actor1->getGlobalPose().p;
    PxVec3 pos2 = actor2->getGlobalPose().p;

    PxQueryFilterData filterData;
    PxQueryReportFlags reportFlags = PxQueryReportFlag::eNONE;

    PxOverlapBuffer buffer;
    PxShape* shapes[1] = {shape2};
    PxQueryFilterData filterData;
    PxQueryReportFlags reportFlags = PxQueryReportFlag::eNONE;

    PxVec3 extents = shape1->getLocalPose().p + shape1->getGeometry().box.halfExtents;
    PxBounds3 bounds = PxBounds3(pos1 - extents, pos1 + extents);

    PxU32 nbResults = scene->overlap(bounds, shapes, 1, filterData, reportFlags, buffer);

    return nbResults > 0;
}
```

