    CollisionSystem() {
        setupPhysX(&physics, &scene);
    }

    ~CollisionSystem() {
        scene->release();
        physics->release();
    }

    void addActor(PxVec3 position, PxVec3 dimensions, PxMaterial* material) {
        PxRigidActor* actor;
        createActor(physics, scene, position, dimensions, material, &actor);
        actors.push_back(actor);
