```python
import datetime

class Sprint:
    def __init__(self, start_date, end_date, tasks, total_hours=30, coverage_target=95):
        self.start_date = start_date
        self.end_date = end_date
        self.tasks = tasks
        self.total_hours = total_hours
        self.coverage_target = coverage_target
        self.hours_spent = 0
        self.coverage_achieved = 0

    def calculate_progress(self):
        today = datetime.date.today()
        if today < self.start_date:
            return 0
        elif today > self.end_date:
            return 100
        else:
            days_elapsed = (today - self.start_date).days
            total_days = (self.end_date - self.start_date).days
            return (days_elapsed / total_days) * 100

    def update_hours_spent(self, hours):
        self.hours_spent += hours
        self.hours_spent = min(self.hours_spent, self.total_hours)

    def update_coverage_achieved(self, coverage):
        self.coverage_achieved += coverage
        self.coverage_achieved = min(self.coverage_achieved, self.coverage_target)

    def get_status(self):
        progress = self.calculate_progress()
        hours_remaining = self.total_hours - self.hours_spent
        coverage_remaining = self.coverage_target - self.coverage__achieved
        return {
            'progress': progress,
            'hours_spent': self.hours_spent,
            'hours_remaining': hours_remaining,
            'coverage_achieved': self.coverage_achieved,
            'coverage_remaining': coverage_remaining
        }

