            return Mathf.Max(0.1f, spawnRate - 0.1f); // Significantly reduce spawn rate
        }

        // Adjust the spawn rate based on the current density
        if (currentDensity > 300) // Example threshold
        {
            return Mathf.Max(0.1f, spawnRate - 0.05f); // Reduce spawn rate
        }
        else if (currentDensity < 200) // Example threshold
        {
            return Mathf.Min(1.0f, spawnRate + 0.05f); // Increase spawn rate
        }
        return spawnRate;
    }

    private IEnumerator ApplySpawnRateWithDelay(float newSpawnRate)
    {
        yield return new WaitForSeconds(adjustmentDelay / 1000f); // Convert milliseconds to seconds

        // Apply the new spawn rate
        ApplyNewSpawnRate(newSpawnRate);
    }

    private void ApplyNewSpawnRate(float newSpawnRate)
    {
        spawnRate = newSpawnRate;
        // Update agent spawn rates
        foreach (PedestrianAgent agent in agents)
        {
            agent.SetSpawnRate(spawnRate);
        }

        // Update the last density for next calculation
        lastDensity = agents.Count;
    }

