class FQuadTree
{
public:
    FQuadTree(const FVector& Center, const FVector& Extent, int32 Depth, int32 Capacity)
        : Center(Center), Extent(Extent), Depth(Depth), Capacity(Capacity)
    {
        if (Depth > 0)
        {
            for (int32 i = 0; i < 4; ++i)
            {
                Children[i] = MakeShared<FQuadTree>(
                    Center + Extent * (FVector(i % 2 ? 1 : -1, i / 2 ? 1 : -1, 0) * 0.5f),
                    Extent * 0.5f,
                    Depth - 1,
                    Capacity
                );
            }
        }
    }

    void Insert(int32 ID, const FVector& Position)
    {
        if (Depth == 0 || !Bounds.Contains(Position))
        {
            Pedestrians.Add(ID, Position);
            return;
