        for (int32 i = 0; i < 4; ++i)
        {
            if (Children[i]->Bounds.Contains(Position))
            {
                Children[i]->Insert(ID, Position);
                break;
            }
        }
    }

    void Query(const FVector& Position, float Radius, TSet<int32>& Results)
    {
        if (!Bounds.Contains(Position))
        {
            return;
        }

        for (auto& Pair : Pedestrians)
        {
            if ((Pair.Value - Position).Size() < Radius)
            {
                Results.Add(Pair.Key);
            }
        }

        if (Depth > 0)
        {
            for (int32 i = 0; i < 4; ++i)
            {
                Children[i]->Query(Position, Radius, Results);
            }
        }
    }

private:
