#### Step 2: Create the Grid Manager

```python
class GridManager:
    def __init__(self, width, height, cell_size):
        self.width = width
        self.height = height
        self.cell_size = cell_size
        self.grid = [[GridCell() for _ in range(width // cell_size)] for _ in range(height // cell_size)]

    def get_cell_coordinates(self, x, y):
        return int(x // self.cell_size), int(y // self.cell_size)

    def add_agent(self, agent):
        cell_x, cell_y = self.get_cell_coordinates(agent.x, agent.y)
        self.grid[cell_x][cell_y].add_agent(agent)

    def remove_agent(self, agent):
        cell_x, cell_y = self.get_cell_coordinates(agent.x, agent.y)
        self.grid[cell_x][cell_y].remove_agent(agent)

    def move_agent(self, agent):
        old_cell_x, old_cell_y = self.get_cell_coordinates(agent.x, agent.y)
        agent.move()
        new_cell_x, new_cell_y = self.get_cell_coordinates(agent.x, agent.y)

        if (old_cell_x, old_cell_y) != (new_cell_x, new_cell_y):
            self.grid[old_cell_x][old_cell_y].remove_agent(agent)
            self.grid[new_cell_x][new_cell_y].add_agent(agent)

    def check_collisions(self):
        for row in self.grid:
            for cell in row:
                cell.check_collisions()
