import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class VisualizationLogic {
    private static final int LATENCY_THRESHOLD = 11;
    private static final int MEMORY_ALLOCATION = 170;

    public static void renderAgents(List<Agent> agents) {
        long startTime = System.nanoTime();

        // Visibility culling
        List<Agent> visibleAgents = new ArrayList<>();
        for (Agent agent : agents) {
            if (agent.isVisible()) {
                visibleAgents.add(agent);
            }
        }

        // Parallel processing
        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        for (Agent agent : visibleAgents) {
            executor.submit(agent::render);
        }

        // Shutdown the executor service
        executor.shutdown();
        try {
            if (!executor.awaitTermination(LATENCY_THRESHOLD, TimeUnit.MILLISECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }

        long endTime = System.nanoTime();
        double latency = (endTime - startTime) / 1_000_000.0; // Convert to milliseconds
        if (latency > LATENCY_THRESHOLD) {
            System.out.println("Latency exceeded threshold: "  + latency + " ms");
        }
