import threading
import json

class ThreadSafeHashIndex:
    def __init__(self):
        self.index = {}
        self.lock = threading.Lock()

    def insert(self, key, value):
        with self.lock:
            self.index[key] = value
            self.get_logger().info(f"Inserted into hash index: {key} - {value}")

    def get(self, key):
        with self.lock:
            return self.index.get(key, None)

    def remove(self, key):
        with self.lock:
            if key in self.index:
                del self.index[key]
                self.get_logger().info(f"Removed from hash index: {key}")

    def check_consistency(self, original_data):
        for key, value in original_data.items():
            if self.get(key) != value:
                raise ValueError(f"Inconsistency detected: {key} - {value}")

