    def publish_message(self):
        msg = String()
        msg.data = 'Debug data'
        self.publisher.publish(msg)
        self.get_logger().info(f"Published data: {msg.data}")

    def listener_callback(self, msg):
        self.get_logger().info(f"Received data: {msg.data}")
        self.hash_index.insert(msg.data, msg.data)
        self.check_consistency(deserialize_data(msg.data))

    def check_consistency(self, original_data):
        try:
            self.hash_index.check_consistency(original_data)
        except ValueError as e:
            self.get_logger().error(f"Consistency check failed: {e}")

def main(args=None):
